class LinearRegressionDataset:
    def __init__(self, csv_file):
        df = pd.read_csv(csv_file)
        self.X = jnp.array(df['X'].values).reshape(-1, 1)
        self.y = jnp.array(df['y'].values).reshape(-1, 1)

    def __len__(self):
        return len(self.X)

# 2. Replicate DataLoader Logic (Generator)
def data_loader(dataset, batch_size, key, shuffle=True):
    indices = jnp.arange(len(dataset))
    if shuffle:
        indices = jax.random.permutation(key, indices)
    for i in range(0, len(dataset), batch_size):
        batch_idx = indices[i:i+batch_size]
        yield dataset.X[batch_idx], dataset.y[batch_idx]

